function renderCatalog(){const q=$('searchInput').value.trim().toLowerCase();const matches=[];for(let i=1;i<=totalSlots;i++){const n=networkAt(i,year);if(!q||String(i).includes(q)||n.name.toLowerCase().includes(q)||n.genre.toLowerCase().includes(q))matches.push({i,n});if(matches.length>=100)break} $('catalog').innerHTML=matches.map(({i,n})=>`<div class="channel-row ${i===current?'selected':''}" data-slot="${i}"><span class="num">${pad(i)}</span><span class="meta"><b>${n.name}</b><small>${n.genre.toUpperCase()} · ${n.year}</small></span><span class="tag">${year>=2002?'DIGI':'ANALOG'}</span></div>`).join('')||'<div class="archive-note">No dial positions match that search. Try a network, genre or channel number.</div>';document.querySelectorAll('.channel-row').forEach(row=>row.addEventListener('click',()=>tune(+row.dataset.slot)))}
function tune(slot){current=Math.max(1,Math.min(totalSlots,slot));$('screen').classList.remove('playing');$('video').pause();$('video').removeAttribute('src');$('video').load();updateStation(true)}
function showToast(message){const t=$('toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
function scan(){if(found.length>=8){showToast('All eight stations found! Keep surfing for points.');tune(Math.floor(Math.random()*totalSlots)+1);return}let slot=current;for(let tries=0;tries<totalSlots;tries++){slot=slot%totalSlots+1;const n=networkAt(slot,year);if(!found.includes(n.name)){tune(slot);showToast(`Clear carrier found: ${n.name}`);return}}tune(Math.floor(Math.random()*totalSlots)+1)}
