$('watchBtn').addEventListener('click',()=>{const v=$('video');v.src=sampleVideo;$('screen').classList.add('playing');$('sourceBox').innerHTML='<b>PUBLIC-DOMAIN DEMO CLIP · NOT A BROADCAST</b><p>Big Buck Bunny sample video, served as a direct MP4 for HTML5 playback. <a href="https://peach.blender.org/" target="_blank" rel="noopener">Blender Foundation film page &amp; credits ↗</a>. Stream availability depends on the host/network.</p>';v.play().catch(()=>showToast('Press play in the video controls to start the sample.'))});$('video').addEventListener('error',()=>{showToast('The sample host did not respond. Try again later.');$('sourceBox').innerHTML='<b>DEMO STREAM UNAVAILABLE</b><p>The public MP4 host did not load. The channel guide and signal hunt remain playable.</p>'});document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA'].includes(document.activeElement.tagName))return;if(e.key==='ArrowRight')tune(current%totalSlots+1);if(e.key==='ArrowLeft')tune(current===1?totalSlots:current-1)});
$('score').textContent=String(score).padStart(3,'0');$('foundCount').textContent=`${Math.min(found.length,8)} / 8`;updateEra();updateStation(false);
</script>
</body>
</html>

